create table public.seo_task_definitions(id text primary key,scope text not null check(scope in ('article','site')),definition jsonb not null);
create table public.seo_targets(
 target_key text primary key,scope text not null check(scope in ('article','site')),
 metadata jsonb not null,content_hash text not null,
 task_states jsonb not null default '{}'::jsonb,last_run jsonb,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.seo_review_runs(
 id uuid primary key,target_key text not null references public.seo_targets(target_key),content_hash text not null,
 report jsonb not null,actor uuid references auth.users(id),created_at timestamptz not null default now()
);
create index seo_runs_target on public.seo_review_runs(target_key,created_at desc);
create table public.seo_task_activity(
 id bigint generated always as identity primary key,target_key text not null references public.seo_targets(target_key),task_id text,
 actor uuid references auth.users(id),action text not null,before_state jsonb,after_state jsonb,created_at timestamptz not null default now()
);
create index seo_activity_target on public.seo_task_activity(target_key,created_at desc);
do $$declare t text;begin foreach t in array array['seo_task_definitions','seo_targets','seo_review_runs','seo_task_activity'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create policy seo_staff_read on public.%I for select to authenticated using ((select public.ops_role()) is not null)',t);
end loop;end $$;

create view public.seo_target_summary with (security_invoker=true) as
 select target_key,metadata,content_hash,last_run,updated_at,
 (select count(*) from jsonb_each(task_states) s where s.value->>'status'='done' and s.value->>'contentHash'=content_hash) as done,
 (select count(*) from jsonb_each(task_states) s where s.value->>'status'='na' and s.value->>'contentHash'=content_hash) as not_applicable,
 (select count(*) from jsonb_each(task_states) s where s.value->>'status'='blocked') as blocked
 from public.seo_targets;
revoke all on public.seo_target_summary from public,anon,authenticated;grant select on public.seo_target_summary to authenticated;

create function content_ops_private.seo_can_write(target text) returns boolean
language sql stable security definer set search_path='' as $$
 select coalesce(public.ops_role() in ('admin','editor','strategist','fact_checker','publisher') or
 (public.ops_role()='writer' and target<>'site' and exists(
 select 1 from public.content_items i join public.seo_targets t on t.target_key=target
 where i.data->>'ownerId'=auth.uid()::text and (i.cms_document_id::text=t.metadata->>'documentId' or i.data->>'publicPath'=t.metadata->>'path'))),false)
$$;
revoke all on function content_ops_private.seo_can_write(text) from public,anon,authenticated;

create function content_ops_private.seo_sync(payload jsonb) returns integer
language plpgsql security definer set search_path='' as $$
declare r text:=public.ops_role(); item jsonb;n integer:=0;previous jsonb;
begin
 if r is null or r not in ('admin','editor','strategist') then raise exception 'FORBIDDEN';end if;
 if jsonb_typeof(payload)<>'array' or jsonb_array_length(payload)>500 then raise exception 'INVALID_DATA';end if;
 for item in select value from jsonb_array_elements(payload) loop
 if coalesce(item->>'key','') !~ '^(site|article:[0-9a-f-]{36})$' or coalesce(item->>'scope','') not in ('site','article') or nullif(item->>'hash','') is null or length(item::text)>10000 then raise exception 'INVALID_DATA';end if;
 if (item->>'scope'='site') is distinct from (item->>'key'='site') then raise exception 'INVALID_DATA';end if;
 select metadata into previous from public.seo_targets where target_key=item->>'key' for update;
 insert into public.seo_targets(target_key,scope,metadata,content_hash) values(item->>'key',item->>'scope',item,item->>'hash')
 on conflict(target_key) do update set metadata=excluded.metadata,content_hash=excluded.content_hash,updated_at=now()
 where seo_targets.metadata is distinct from excluded.metadata or seo_targets.content_hash is distinct from excluded.content_hash;
 if previous is distinct from item then insert into public.seo_task_activity(target_key,actor,action,before_state,after_state) values(item->>'key',auth.uid(),'sync_target',previous,item);end if;
 n:=n+1;
 end loop;return n;
end $$;
revoke all on function content_ops_private.seo_sync(jsonb) from public,anon;
grant execute on function content_ops_private.seo_sync(jsonb) to authenticated;
create function public.seo_sync(payload jsonb) returns integer language sql security invoker set search_path='' as $$select content_ops_private.seo_sync(payload)$$;
revoke all on function public.seo_sync(jsonb) from public,anon;grant execute on function public.seo_sync(jsonb) to authenticated;

create function content_ops_private.seo_set_task(target text,task text,state jsonb,expected_version integer,expected_hash text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare current_row public.seo_targets;def public.seo_task_definitions;old_state jsonb;next_state jsonb;r text:=public.ops_role();owner_id uuid:=nullif(state->>'ownerId','')::uuid;
begin
 if not content_ops_private.seo_can_write(target) then raise exception 'FORBIDDEN';end if;
 if expected_version is null or expected_version<0 then raise exception 'VERSION_CONFLICT';end if;
 select * into current_row from public.seo_targets where target_key=target for update;
 if not found then raise exception 'NOT_FOUND';end if;
 if expected_hash is distinct from current_row.content_hash then raise exception 'CONTENT_CHANGED';end if;
 select * into def from public.seo_task_definitions where id=task;
 if not found or def.scope<>current_row.scope then raise exception 'TASK_SCOPE_MISMATCH';end if;
 old_state:=current_row.task_states->task;
 if coalesce((old_state->>'version')::integer,0)<>expected_version then raise exception 'VERSION_CONFLICT';end if;
 if coalesce(state->>'status','') not in ('pending','working','done','blocked','na') or length(state::text)>12000 then raise exception 'INVALID_DATA';end if;
 if state->>'status' in ('done','blocked','na') and length(trim(coalesce(state->>'note','')))<10 then raise exception 'EVIDENCE_REQUIRED';end if;
 if coalesce((def.definition->>'protected')::boolean,false) and state->>'status'='done' and r not in ('admin','editor','fact_checker') then raise exception 'APPROVAL_FORBIDDEN';end if;
 if owner_id is not null and not (exists(select 1 from public.ops_members where user_id=owner_id and active) or exists(select 1 from public.cms_admins where user_id=owner_id)) then raise exception 'OWNER_REQUIRED';end if;
 next_state:=jsonb_build_object('status',state->>'status','note',left(coalesce(state->>'note',''),6000),'evidence',left(coalesce(state->>'evidence',''),3000),'ownerId',owner_id,'dueAt',nullif(state->>'dueAt','')::timestamptz,'priority',case when state->>'priority' in ('low','normal','high','critical') then state->>'priority' else 'normal' end,'version',expected_version+1,'contentHash',current_row.content_hash,'reviewedAt',now(),'reviewedBy',auth.uid());
 update public.seo_targets set task_states=task_states||jsonb_build_object(task,next_state),updated_at=now() where target_key=target;
 insert into public.seo_task_activity(target_key,task_id,actor,action,before_state,after_state) values(target,task,auth.uid(),'task_update',old_state,next_state);
 return next_state;
end $$;
revoke all on function content_ops_private.seo_set_task(text,text,jsonb,integer,text) from public,anon;
grant execute on function content_ops_private.seo_set_task(text,text,jsonb,integer,text) to authenticated;
create function public.seo_set_task(target text,task text,state jsonb,expected_version integer,expected_hash text) returns jsonb language sql security invoker set search_path='' as $$select content_ops_private.seo_set_task(target,task,state,expected_version,expected_hash)$$;
revoke all on function public.seo_set_task(text,text,jsonb,integer,text) from public,anon;grant execute on function public.seo_set_task(text,text,jsonb,integer,text) to authenticated;

create function content_ops_private.seo_record_run(run_id uuid,target text,hash text,report jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;r text:=public.ops_role();
begin
 if r is null or r not in ('admin','editor','strategist') then raise exception 'FORBIDDEN';end if;
 if run_id is null or report is null or jsonb_typeof(report)<>'object' or coalesce(jsonb_typeof(report->'checks'),'null')<>'array' or length(report::text)>150000 then raise exception 'INVALID_DATA';end if;
 if not exists(select 1 from public.seo_targets where target_key=target and content_hash=hash) then raise exception 'CONTENT_CHANGED';end if;
 insert into public.seo_review_runs(id,target_key,content_hash,report,actor) values(run_id,target,hash,report,auth.uid()) on conflict(id) do nothing;
 select to_jsonb(t) into result from public.seo_review_runs t where id=run_id;
 if result->>'target_key' is distinct from target or result->>'content_hash' is distinct from hash then raise exception 'RUN_CONFLICT';end if;
 update public.seo_targets set last_run=jsonb_build_object('id',run_id,'hash',hash,'checkedAt',report->>'checkedAt','mode',report->>'mode','createdAt',result->>'created_at','failures',(select count(*) from jsonb_array_elements(report->'checks') c where c->>'status' in ('fail','error')),'warnings',(select count(*) from jsonb_array_elements(report->'checks') c where c->>'status'='warning'),'passed',(select count(*) from jsonb_array_elements(report->'checks') c where c->>'status'='pass'))
 where target_key=target and (last_run is null or (last_run->>'createdAt')::timestamptz<=(result->>'created_at')::timestamptz);
 return result;
end $$;
revoke all on function content_ops_private.seo_record_run(uuid,text,text,jsonb) from public,anon;grant execute on function content_ops_private.seo_record_run(uuid,text,text,jsonb) to authenticated;
create function public.seo_record_run(run_id uuid,target text,hash text,report jsonb) returns jsonb language sql security invoker set search_path='' as $$select content_ops_private.seo_record_run(run_id,target,hash,report)$$;
revoke all on function public.seo_record_run(uuid,text,text,jsonb) from public,anon;grant execute on function public.seo_record_run(uuid,text,text,jsonb) to authenticated;

insert into public.seo_task_definitions(id,scope,definition) select id,scope,definition from jsonb_to_recordset($seo_definitions$[{"id":"SEO-001","scope":"article","definition":{"id":"SEO-001","order":1,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"تحديد الجمهور ومشكلة القارئ الحقيقية","original":"Identify the audience and the real problem the article should solve.","protected":false,"version":1}},{"id":"SEO-002","scope":"article","definition":{"id":"SEO-002","order":2,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"تحديد المجموعة الموضوعية والكلمات الأولية","original":"Identify relevant topic clusters and seed keywords.","protected":false,"version":1}},{"id":"SEO-003","scope":"article","definition":{"id":"SEO-003","order":3,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"بحث الطلب وصعوبة المنافسة الواقعية","original":"Research keyword demand and realistic ranking difficulty.","protected":false,"version":1}},{"id":"SEO-004","scope":"article","definition":{"id":"SEO-004","order":4,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"تحديد الكلمات الطويلة وصيغ الأسئلة","original":"Identify long-tail and question-based keywords.","protected":false,"version":1}},{"id":"SEO-005","scope":"article","definition":{"id":"SEO-005","order":5,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"تحديد نية البحث وأنواعها","original":"Evaluate informational, transactional, and navigational search intent.","protected":false,"version":1}},{"id":"SEO-006","scope":"article","definition":{"id":"SEO-006","order":6,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"بحث أسئلة الجمهور في المجتمعات ونتائج البحث","original":"Research audience questions in forums, communities, and search results.","protected":false,"version":1}},{"id":"SEO-007","scope":"article","definition":{"id":"SEO-007","order":7,"scope":"article","group":"research","groupTitle":"الجمهور والبحث","title":"تحديد زاوية أصلية وفجوات مفيدة","original":"Identify an original angle and meaningful information gaps.","protected":false,"version":1}},{"id":"SEO-008","scope":"article","definition":{"id":"SEO-008","order":8,"scope":"article","group":"competitors","groupTitle":"تحليل المنافسين","title":"مراجعة الصفحات المتصدرة للموضوع","original":"Review top-ranking pages for the primary topic.","protected":false,"version":1}},{"id":"SEO-009","scope":"article","definition":{"id":"SEO-009","order":9,"scope":"article","group":"competitors","groupTitle":"تحليل المنافسين","title":"حصر العناوين والموضوعات والأسئلة المتكررة","original":"Identify recurring headings, topics, and reader questions.","protected":false,"version":1}},{"id":"SEO-010","scope":"article","definition":{"id":"SEO-010","order":10,"scope":"article","group":"competitors","groupTitle":"تحليل المنافسين","title":"تحليل تنسيقات المنافسين وعمق المحتوى","original":"Analyze competitor content formats and depth.","protected":false,"version":1}},{"id":"SEO-011","scope":"article","definition":{"id":"SEO-011","order":11,"scope":"article","group":"competitors","groupTitle":"تحليل المنافسين","title":"مقارنة العناوين والأوصاف وظهورها في البحث","original":"Compare titles, descriptions, and SERP presentation.","protected":false,"version":1}},{"id":"SEO-012","scope":"article","definition":{"id":"SEO-012","order":12,"scope":"article","group":"competitors","groupTitle":"تحليل المنافسين","title":"تحديد معلومات عملية أو حقائق يفتقدها المنافسون","original":"Find factual or practical information missing from competitors.","protected":false,"version":1}},{"id":"SEO-013","scope":"article","definition":{"id":"SEO-013","order":13,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"اختيار تنسيق مناسب لنية البحث","original":"Choose the article format best suited to search intent.","protected":false,"version":1}},{"id":"SEO-014","scope":"article","definition":{"id":"SEO-014","order":14,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"تحديد وعد المقال ونطاقه","original":"Define the article's central promise and scope.","protected":false,"version":1}},{"id":"SEO-015","scope":"article","definition":{"id":"SEO-015","order":15,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"إنشاء هيكل منطقي بعناوين H2 وH3","original":"Create a logical H2/H3 outline.","protected":false,"version":1}},{"id":"SEO-016","scope":"article","definition":{"id":"SEO-016","order":16,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"ترتيب الأسئلة والإجابات بما يخدم القارئ","original":"Organize questions and answers in reader-friendly order.","protected":false,"version":1}},{"id":"SEO-017","scope":"article","definition":{"id":"SEO-017","order":17,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"تخطيط التعريفات والخطوات والأمثلة وحلول المشكلات","original":"Include definitions, instructions, examples, and troubleshooting where relevant.","protected":false,"version":1}},{"id":"SEO-018","scope":"article","definition":{"id":"SEO-018","order":18,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"إزالة العناوين المتداخلة والأفكار المكررة","original":"Remove overlapping headings and repeated ideas.","protected":false,"version":1}},{"id":"SEO-019","scope":"article","definition":{"id":"SEO-019","order":19,"scope":"article","group":"outline","groupTitle":"النطاق والهيكل","title":"تخطيط الروابط الداخلية والمصادر والوسائط","original":"Plan internal links, sources, and supporting visuals.","protected":false,"version":1}},{"id":"SEO-020","scope":"article","definition":{"id":"SEO-020","order":20,"scope":"article","group":"headline","groupTitle":"العنوان","title":"صياغة عنوان يوضح فائدة القارئ","original":"Create a headline with a clear reader benefit.","protected":false,"version":1}},{"id":"SEO-021","scope":"article","definition":{"id":"SEO-021","order":21,"scope":"article","group":"headline","groupTitle":"العنوان","title":"إدراج الكلمة الأساسية طبيعيًا في العنوان","original":"Include the primary keyword naturally in the title.","protected":false,"version":1}},{"id":"SEO-022","scope":"article","definition":{"id":"SEO-022","order":22,"scope":"article","group":"headline","groupTitle":"العنوان","title":"استخدام الأرقام والمحددات عند فائدتها","original":"Use specificity, numbers, or modifiers only when useful.","protected":false,"version":1}},{"id":"SEO-023","scope":"article","definition":{"id":"SEO-023","order":23,"scope":"article","group":"headline","groupTitle":"العنوان","title":"تجنب المبالغة والوعود المضللة في العنوان","original":"Avoid exaggerated or misleading headline claims.","protected":false,"version":1}},{"id":"SEO-024","scope":"article","definition":{"id":"SEO-024","order":24,"scope":"article","group":"intro","groupTitle":"المقدمة","title":"الإجابة المبكرة عن سؤال القارئ الأساسي","original":"Answer the central reader question early in the introduction.","protected":false,"version":1}},{"id":"SEO-025","scope":"article","definition":{"id":"SEO-025","order":25,"scope":"article","group":"intro","groupTitle":"المقدمة","title":"توضيح أهمية الموضوع وما يقدمه المقال","original":"Explain why the subject matters and what the article will deliver.","protected":false,"version":1}},{"id":"SEO-026","scope":"article","definition":{"id":"SEO-026","order":26,"scope":"article","group":"intro","groupTitle":"المقدمة","title":"كتابة مقدمة قصيرة ومباشرة","original":"Keep the introduction short, compelling, and relevant.","protected":false,"version":1}},{"id":"SEO-027","scope":"article","definition":{"id":"SEO-027","order":27,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"كتابة شرح شامل ومحدد النطاق","original":"Write comprehensive but focused explanations.","protected":false,"version":1}},{"id":"SEO-028","scope":"article","definition":{"id":"SEO-028","order":28,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"استخدام لغة طبيعية وفقرات قصيرة","original":"Use clear, natural language and short paragraphs.","protected":false,"version":1}},{"id":"SEO-029","scope":"article","definition":{"id":"SEO-029","order":29,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"إضافة خطوات وأمثلة أو دراسات حالة قابلة للتطبيق","original":"Include actionable steps, examples, or case studies.","protected":false,"version":1}},{"id":"SEO-030","scope":"article","definition":{"id":"SEO-030","order":30,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"إضافة بحث أصلي أو خبرة حقيقية أو تفاصيل متحقق منها","original":"Add original research, firsthand insights, or independently verified details.","protected":false,"version":1}},{"id":"SEO-031","scope":"article","definition":{"id":"SEO-031","order":31,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"استخدام مصطلحات الموضوع والكلمات المرتبطة طبيعيًا","original":"Incorporate relevant terminology and semantic keywords naturally.","protected":false,"version":1}},{"id":"SEO-032","scope":"article","definition":{"id":"SEO-032","order":32,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"استخدام الجداول والقوائم لتوضيح المقارنات","original":"Use tables and lists to clarify complex comparisons.","protected":false,"version":1}},{"id":"SEO-033","scope":"article","definition":{"id":"SEO-033","order":33,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"إضافة صور أو مخططات أو فيديو عند الحاجة","original":"Add screenshots, diagrams, or videos where they help understanding.","protected":false,"version":1}},{"id":"SEO-034","scope":"article","definition":{"id":"SEO-034","order":34,"scope":"article","group":"writing","groupTitle":"الكتابة والقيمة الأصلية","title":"التأكد من فائدة كل قسم","original":"Ensure every section contributes useful information.","protected":false,"version":1}},{"id":"SEO-035","scope":"article","definition":{"id":"SEO-035","order":35,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"مراجعة المواد المولدة بالذكاء الاصطناعي والتحقق منها","original":"Review and fact-check any AI-generated material.","protected":true,"version":1}},{"id":"SEO-036","scope":"article","definition":{"id":"SEO-036","order":36,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"التحقق من الحقائق والأرقام والمواعيد والمصادر","original":"Check all facts, numbers, dates, and sources.","protected":true,"version":1}},{"id":"SEO-037","scope":"article","definition":{"id":"SEO-037","order":37,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"مراجعة دقة الإسناد والاقتباسات","original":"Verify that all quoted or referenced information is accurately attributed.","protected":true,"version":1}},{"id":"SEO-038","scope":"article","definition":{"id":"SEO-038","order":38,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"تصحيح الإملاء والنحو والصياغة","original":"Correct spelling, grammar, and awkward sentences.","protected":false,"version":1}},{"id":"SEO-039","scope":"article","definition":{"id":"SEO-039","order":39,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"إزالة الحشو والتكرار","original":"Remove repetitive or filler text.","protected":false,"version":1}},{"id":"SEO-040","scope":"article","definition":{"id":"SEO-040","order":40,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"قراءة المقاطع الصعبة لتحسين الوضوح","original":"Read difficult sections aloud to improve clarity.","protected":false,"version":1}},{"id":"SEO-041","scope":"article","definition":{"id":"SEO-041","order":41,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"مراجعة البنية والانتقالات وتسلسل الفقرات","original":"Review structure, transitions, and paragraph flow.","protected":false,"version":1}},{"id":"SEO-042","scope":"article","definition":{"id":"SEO-042","order":42,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"التأكد من خدمة الأمثلة والوسائط للمحتوى","original":"Ensure examples and visuals support the content.","protected":false,"version":1}},{"id":"SEO-043","scope":"article","definition":{"id":"SEO-043","order":43,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"مراجعة الأصالة والفائدة العملية والاكتمال","original":"Check for originality, practical usefulness, and completeness.","protected":false,"version":1}},{"id":"SEO-044","scope":"article","definition":{"id":"SEO-044","order":44,"scope":"article","group":"verification","groupTitle":"التحقق والتحرير","title":"إتمام الاعتماد التحريري البشري النهائي","original":"Complete the final human editorial approval.","protected":true,"version":1}},{"id":"SEO-045","scope":"article","definition":{"id":"SEO-045","order":45,"scope":"article","group":"approval","groupTitle":"الاعتماد والنشر","title":"التأكد من وفاء المقال بوعد العنوان","original":"Confirm that the article delivers on its headline.","protected":false,"version":1}},{"id":"SEO-046","scope":"article","definition":{"id":"SEO-046","order":46,"scope":"article","group":"approval","groupTitle":"الاعتماد والنشر","title":"إضافة خطوة تالية أو إجراء مفيد","original":"Add a helpful next-step or call to action.","protected":false,"version":1}},{"id":"SEO-047","scope":"article","definition":{"id":"SEO-047","order":47,"scope":"article","group":"approval","groupTitle":"الاعتماد والنشر","title":"ربط المقالات والأدوات ذات الصلة","original":"Link to related articles or tools where appropriate.","protected":false,"version":1}},{"id":"SEO-048","scope":"article","definition":{"id":"SEO-048","order":48,"scope":"article","group":"approval","groupTitle":"الاعتماد والنشر","title":"تجهيز جميع الأصول المطلوبة","original":"Ensure all required supporting assets are ready.","protected":false,