يل الأداء حسب المقال والمجموعة والموقع والجهاز","original":"Analyze performance by article, topic cluster, location, and device.","protected":false,"version":1}},{"id":"SEO-152","scope":"site","definition":{"id":"SEO-152","order":152,"scope":"site","group":"measurement","groupTitle":"القياس والتحسين","title":"متابعة الفترة من النشر إلى الاكتشاف والفهرسة","original":"Monitor publication-to-discovery and indexation trends.","protected":false,"version":1}},{"id":"SEO-153","scope":"site","definition":{"id":"SEO-153","order":153,"scope":"site","group":"measurement","groupTitle":"القياس والتحسين","title":"تحديد المقالات المتراجعة وأولويات التحديث الحقيقي","original":"Detect declining articles and prioritize meaningful refreshes.","protected":false,"version":1}},{"id":"SEO-154","scope":"site","definition":{"id":"SEO-154","order":154,"scope":"site","group":"measurement","groupTitle":"القياس والتحسين","title":"تكرار الزحف والتدقيق الفني بانتظام","original":"Repeat website crawling and technical audits regularly.","protected":false,"version":1}},{"id":"SEO-155","scope":"site","definition":{"id":"SEO-155","order":155,"scope":"site","group":"measurement","groupTitle":"القياس والتحسين","title":"مراجعة أثر الروابط الداخلية وتحديثات المحتوى","original":"Review the effectiveness of internal linking and content updates.","protected":false,"version":1}},{"id":"SEO-156","scope":"site","definition":{"id":"SEO-156","order":156,"scope":"site","group":"measurement","groupTitle":"القياس والتحسين","title":"حفظ قائمة مشكلات SEO بأصحابها وأولوياتها ومواعيدها","original":"Maintain an SEO issue backlog with owners, priorities, and deadlines.","protected":false,"version":1}},{"id":"SEO-157","scope":"site","definition":{"id":"SEO-157","order":157,"scope":"site","group":"measurement","groupTitle":"القياس والتحسين","title":"قياس النتائج بعد التحسينات الكبيرة","original":"Measure outcomes after major optimization changes.","protected":false,"version":1}},{"id":"SEO-158","scope":"site","definition":{