criptive URL paths.","protected":false,"version":1}},{"id":"SEO-165","scope":"site","definition":{"id":"SEO-165","order":165,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"تحديد نسخة HTTPS ونطاق أساسي واحد","original":"Define one preferred HTTPS and www/non-www domain version.","protected":false,"version":1}},{"id":"SEO-166","scope":"site","definition":{"id":"SEO-166","order":166,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"إضافة canonical ذاتي صحيح للصفحات الأساسية","original":"Add correct self-referencing canonical tags to primary indexable pages.","protected":false,"version":1}},{"id":"SEO-167","scope":"site","definition":{"id":"SEO-167","order":167,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"توجيه النسخ البديلة والمكررة إلى الصفحة المقصودة","original":"Point duplicate and alternate URLs to the intended canonical page.","protected":false,"version":1}},{"id":"SEO-168","scope":"site","definition":{"id":"SEO-168","order":168,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"مطابقة إشارات canonical والتحويلات والخريطة والروابط","original":"Check canonical, redirect, sitemap, and internal-link signals for consistency.","protected":false,"version":1}},{"id":"SEO-169","scope":"site","definition":{"id":"SEO-169","order":169,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"تدقيق حظر الزحف غير المقصود في robots","original":"Audit robots.txt rules for unintended crawling restrictions.","protected":false,"version":1}},{"id":"SEO-170","scope":"site","definition":{"id":"SEO-170","order":170,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"تأكيد عدم حظر CSS وJavaScript والصور المهمة","original":"Ensure critical CSS, JavaScript, and images are not blocked.","protected":false,"version":1}},{"id":"SEO-171","scope":"site","definition":{"id":"SEO-171","order":171,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"حصر الخريطة في روابط أساسية مفيدة تستجيب 200","original":"Keep XML sitemaps limited to useful canonical, indexable URLs returning HTTP 200.","protected":false,"version":1}},{"id":"SEO-172","scope":"site","definition":{"id":"SEO-172","order":172,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"استبعاد التحويلات والأخطاء والمكررات من الخريطة","original":"Exclude redirects, errors, and duplicate URLs from XML sitemaps.","protected":false,"version":1}},{"id":"SEO-173","scope":"site","definition":{"id":"SEO-173","order":173,"scope":"site","group":"canonical-crawl","groupTitle":"توحيد الروابط والزحف","title":"التحقق من إرسال الخريطة ومعالجتها في Search Console","original":"Validate sitemap submission and processing in Google Search Console.","protected":false,"version":1}},{"id":"SEO-174","scope":"site","definition":{"id":"SEO-174","order":174,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"تحديد الصفحات المهمة التي لا تُكتشف","original":"Identify important pages that search engines cannot discover.","protected":false,"version":1}},{"id":"SEO-175","scope":"site","definition":{"id":"SEO-175","order":175,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"بحث أسباب استبعاد الروابط المهمة من فهرس Google","original":"Investigate important URLs excluded from Google's index.","protected":false,"version":1}},{"id":"SEO-176","scope":"site","definition":{"id":"SEO-176","order":176,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"فصل تشخيص المكتشف عن المزحوف غير المفهرس","original":"Diagnose Discovered – currently not indexed and Crawled – currently not indexed separately.","protected":false,"version":1}},{"id":"SEO-177","scope":"site","definition":{"id":"SEO-177","order":177,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"فحص noindex والحظر وتعارض canonical غير المقصود","original":"Check accidental noindex directives, robots blocks, and canonical conflicts.","protected":false,"version":1}},{"id":"SEO-178","scope":"site","definition":{"id":"SEO-178","order":178,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"تأكيد وجود نص المقال وروابطه في HTML الأولي","original":"Verify that important article text and links appear in server-rendered or initial HTML.","protected":false,"version":1}},{"id":"SEO-179","scope":"site","definition":{"id":"SEO-179","order":179,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"اختبار الصفحات دون JavaScript وبزاحف مع العرض","original":"Test key pages with JavaScript disabled and with a rendered crawler.","protected":false,"version":1}},{"id":"SEO-180","scope":"site","definition":{"id":"SEO-180","order":180,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"تأكيد استخدام روابط HTML قابلة للزحف للتنقل","original":"Verify that internal navigation uses crawlable HTML links.","protected":false,"version":1}},{"id":"SEO-181","scope":"site","definition":{"id":"SEO-181","order":181,"scope":"site","group":"render-index","groupTitle":"العرض والفهرسة","title":"استخدام فحص URL بعد الإصلاحات","original":"Use URL Inspection to verify selected pages after fixes.","protected":false,"version":1}},{"id":"SEO-182","scope":"site","definition":{"id":"SEO-182","order":182,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"قياس LCP عند الشريحة المئوية 75 واستهداف 2.5 ثانية","original":"Measure LCP; target 2.5 seconds or less at the 75th percentile.","protected":false,"version":1}},{"id":"SEO-183","scope":"site","definition":{"id":"SEO-183","order":183,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"قياس INP عند الشريحة المئوية 75 واستهداف 200 مللي ثانية","original":"Measure INP; target 200 milliseconds or less at the 75th percentile.","protected":false,"version":1}},{"id":"SEO-184","scope":"site","definition":{"id":"SEO-184","order":184,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"قياس CLS عند الشريحة المئوية 75 واستهداف 0.1","original":"Measure CLS; target 0.1 or less at the 75th percentile.","protected":false,"version":1}},{"id":"SEO-185","scope":"site","definition":{"id":"SEO-185","order":185,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"فحص حجم العرض والنص وأهداف اللمس على الهاتف","original":"Check mobile viewport, text legibility, and touch-target usability.","protected":false,"version":1}},{"id":"SEO-186","scope":"site","definition":{"id":"SEO-186","order":186,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"تأكيد توفر المحتوى المهم في نسخة الهاتف","original":"Verify that important content is available on the mobile version.","protected":false,"version":1}},{"id":"SEO-187","scope":"site","definition":{"id":"SEO-187","order":187,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"تشخيص المهلات و5xx وDNS وsoft 404","original":"Investigate server timeouts, 5xx responses, DNS errors, and soft 404s.","protected":false,"version":1}},{"id":"SEO-188","scope":"site","definition":{"id":"SEO-188","order":188,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"فحص شهادات HTTPS وإعداد النطاقات الفرعية","original":"Ensure HTTPS certificates and subdomains are configured correctly.","protected":false,"version":1}},{"id":"SEO-189","scope":"site","definition":{"id":"SEO-189","order":189,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"رصد الموارد المختلطة والتحويلات غير المتسقة","original":"Detect mixed HTTP/HTTPS resources and inconsistent redirects.","protected":false,"version":1}},{"id":"SEO-190","scope":"site","definition":{"id":"SEO-190","order":190,"scope":"site","group":"vitals","groupTitle":"مؤشرات الويب والموثوقية","title":"متابعة الإتاحة واس