EO-197","scope":"site","definition":{"id":"SEO-197","order":197,"scope":"site","group":"html-schema","groupTitle":"HTML والبيانات المنظمة","title":"فحص صياغة Schema وأهلية نتائج Google المدعومة","original":"Validate schema syntax and Google rich-result eligibility where applicable.","protected":false,"version":1}},{"id":"SEO-198","scope":"site","definition":{"id":"SEO-198","order":198,"scope":"site","group":"html-schema","groupTitle":"HTML والبيانات المنظمة","title":"توحيد بيانات الكاتب وتاريخ النشر والصورة","original":"Keep article author, publication date, and image metadata consistent.","protected":false,"version":1}},{"id":"SEO-199","scope":"site","definition":{"id":"SEO-199","order":199,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"إضافة Organization دقيق في الصفحات المناسبة","original":"Provide accurate Organization structured data on appropriate pages.","protected":false,"version":1}},{"id":"SEO-200","scope":"site","definition":{"id":"SEO-200","order":200,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"توحيد العلامة والشعار وبيانات الاتصال والملفات الرسمية","original":"Keep brand name, logo, contact details, and official profiles consistent.","protected":false,"version":1}},{"id":"SEO-201","scope":"site","definition":{"id":"SEO-201","order":201,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"استخدام sameAs للملفات الرسمية المتحقق منها فقط","original":"Use sameAs references only for verified official profiles.","protected":false,"version":1}},{"id":"SEO-202","scope":"site","definition":{"id":"SEO-202","order":202,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"ربط سير الكتّاب بمقالاتهم","original":"Connect author biographies to their associated articles.","protected":false,"version":1}},{"id":"SEO-203","scope":"site","definition":{"id":"SEO-203","order":203,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"توضيح الهوية التحريرية في صفحات التعريف والسياسات","original":"Make the website's editorial identity clear on About and policy pages.","protected":false,"version":1}},{"id":"SEO-204","scope":"site","definition":{"id":"SEO-204","order":204,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"اتخاذ قرار مقصود لصلاحيات زواحف AI المناسبة","original":"Review access rules for relevant AI crawlers and make intentional policy decisions.","protected":false,"version":1}},{"id":"SEO-205","scope":"site","definition":{"id":"SEO-205","order":205,"scope":"site","group":"identity","groupTitle":"الهوية والكيانات","title":"تأكيد قابلية قراءة المحتوى آليًا دون الاعتماد الكامل على JavaScript","original":"Verify that public article content is machine-readable without depending entirely on JavaScript.","protected":false,"version":1}},{"id":"SEO-206","scope":"site","definition":{"id":"SEO-206","order":206,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"فحص إحصاءات الزحف في Search Console دوريًا","original":"Inspect Google Search Console crawl statistics regularly.","protected":false,"version":1}},{"id":"SEO-207","scope":"site","definition":{"id":"SEO-207","order":207,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"مراجعة سجلات الزواحف عند توفرها من الاستضافة","original":"Review crawler logs where hosting infrastructure provides them.","protected":false,"version":1}},{"id":"SEO-208","scope":"site","definition":{"id":"SEO-208","order":208,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"تحديد طلبات الزواحف المتكررة للأخطاء والتحويلات والحظر","original":"Identify repeated bot requests to errors, redirects, or blocked URLs.","protected":false,"version":1}},{"id":"SEO-209","scope":"site","definition":{"id":"SEO-209","order":209,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"تنفيذ تدقيق زحف فني شامل ربع سنوي على الأقل","original":"Run a comprehensive crawl-based technical audit at least quarterly.","protected":false,"version":1}},{"id":"SEO-210","scope":"site","definition":{"id":"SEO-210","order":210,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"إعادة التدقيق بعد النشر الكبير أو تغيير CMS","original":"Repeat technical audits following major deployments or CMS changes.","protected":false,"version":1}},{"id":"SEO-211","scope":"site","definition":{"id":"SEO-211","order":211,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"متابعة التغيرات المهمة في فشل الزحف والفهرسة","original":"Track significant changes in crawl failures and indexing status.","protected":false,"version":1}},{"id":"SEO-212","scope":"site","definition":{"id":"SEO-212","order":212,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"متابعة الروابط المعطلة والمكررات والبيانات الناقصة","original":"Monitor broken links, duplicate pages, and missing metadata.","protected":false,"version":1}},{"id":"SEO-213","scope":"site","definition":{"id":"SEO-213","order":213,"scope":"site","group":"monitoring","groupTitle":"المراقبة والتدقيق الدوري","title":"ترتيب المشكلات الفنية والتحقق من الإصلاحات","original":"Maintain a prioritized technical SEO issue backlog with verification after fixes.","protected":false,"version":1}},{"id":"SEO-214","scope":"article","definition":{"id":"SEO-214","order":214,"scope":"article","group":"search-snippet","groupTitle":"عنوان ووصف نتائج البحث","title":"كتابة عنوان SEO فريد للصفحة","original":"Write a unique SEO title for the page.","protected":false,"version":1}},{"id":"SEO-215","scope":"article","definition":{"id":"SEO-215","order":215,"scope":"article","group":"search-snippet","groupTitle":"عنوان ووصف نتائج البحث","title":"تقديم الكلمة الأساسية في العنوان بصورة طبيعية","original":"Include the main keyword near the beginning when natural.","protected":false,"version":1}},{"id":"SEO-216","scope":"article","definition":{"id"